custom_css:
/* ============================================================
 * Gruvbox Dark + HarmonyOS Sans SC
 * 从零编写，不基于任何模板
 * ============================================================ */

/* ---字体加载--- */
@import url('https://cdn.jsdelivr.net/npm/@fontsource/jetbrains-mono@5.0.0/index.css');
@import url('https://cdn.jsdelivr.net/npm/@lobehub/webfont-harmony-sans-sc@1.0.0/css/index-full.css');

/* ---字体变量--- */
:root {
  --font-sans: 'HarmonyOS Sans SC', system-ui, sans-serif;
  --font-serif: 'HarmonyOS Sans SC', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', 'Cascadia Code', ui-monospace, Menlo, Consolas, 'HarmonyOS Sans SC', monospace;
}

/* ---全局字体（排除图标）--- */
body {
  background-color: transparent !important;
  font-family: var(--font-sans);
}

.mes_text,
.mes_text p,
.mes_text span,
.ch_name,
.mesIDDisplay,
.mes_timer,
.tokenCounterDisplay {
  font-family: var(--font-sans);
}

/* 代码等宽 */
code, pre, .hljs, .katex,
.mes_text code, .mes_text pre,
.mes_text .hljs, .mes_text .hljs span,
pre code, pre code.hljs {
  font-family: var(--font-mono) !important;
}

/* ============================================================
 * 引号文本 - 左竖线 + 底色 + 微缩进 组合拳
 * SillyTavern 用 <q> 标签包裹引号文字
 * ============================================================ */
.mes_text q {
  font-family: var(--font-serif) !important;
  color: var(--SmartThemeQuoteColor) !important;
  background: color-mix(in srgb, var(--SmartThemeQuoteColor) 10%, transparent);
  border-left: 3px solid var(--SmartThemeQuoteColor);
  padding: 0 6px 0 8px;
  margin: 0 2px;
  border-radius: 0 4px 4px 0;
  text-decoration: none !important;
}

/* blockquote 也留着以防有用 */
.mes_text blockquote {
  font-family: var(--font-serif) !important;
  border-left: 3px solid var(--SmartThemeQuoteColor);
  background: color-mix(in srgb, var(--SmartThemeQuoteColor) 10%, transparent);
  padding: 8px 12px 8px 14px;
  margin: 4px 0 4px 8px;
  border-radius: 0 4px 4px 0;
}

/* ============================================================
 * 代码块
 * ============================================================ */
code {
  background-color: var(--SmartThemeShadowColor);
  border-radius: 3px;
  padding: 1px 4px;
  font-size: 0.9em;
}

pre {
  background-color: var(--SmartThemeShadowColor) !important;
  border-radius: 6px;
  padding: 12px;
  overflow-x: auto;
}

pre code {
  background: transparent !important;
  padding: 0;
  border-radius: 0;
}

pre code.hljs {
  background: transparent !important;
}

.hljs {
  background: var(--SmartThemeShadowColor);
  border-radius: 6px;
}

/* ============================================================
 * 滚动条
 * ============================================================ */
::-webkit-scrollbar {
  width: 6px;
}
::-webkit-scrollbar:horizontal {
  height: 6px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, var(--SmartThemeQuoteColor) 50%, transparent);
  border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--SmartThemeQuoteColor);
}

/* ============================================================
 * 顶栏
 * ============================================================ */
#top-bar {
  background-color: transparent !important;
  box-shadow: 0 1px 0 var(--SmartThemeBorderColor);
}

#top-settings-holder {
  box-shadow: 0 1px 0 var(--SmartThemeQuoteColor);
}

.drawer {
  background-color: var(--SmartThemeBorderColor);
}

.drawer:has(.openDrawer) {
  background-color: var(--SmartThemeBlurTintColor);
}

.drawer-content {
  background-color: var(--SmartThemeBlurTintColor);
  border-radius: 6px;
  box-shadow: 0 1px 0 var(--SmartThemeQuoteColor);
  border: 1px solid var(--SmartThemeBorderColor);
}

.drawer-icon {
  opacity: 0.5;
}

.drawer-icon:hover,
.drawer-icon.openIcon {
  opacity: 1;
}

/* ---抽屉标题--- */
.inline-drawer-header,
#top-settings-holder h4:not(#ai-config-button *):not(#rightNavHolder *),
.drawer-content h4.margin0 {
  border: 1px solid var(--SmartThemeBorderColor) !important;
  border-left: 3px solid var(--SmartThemeQuoteColor) !important;
  border-radius: 4px !important;
  background-image: none !important;
  background-color: color-mix(in srgb, var(--SmartThemeBorderColor) 60%, var(--SmartThemeBlurTintColor)) !important;
  padding: 4px 8px 4px 12px !important;
  margin-bottom: 4px !important;
}

.inline-drawer-icon {
  font-size: var(--mainFontSize);
}

/* ---标题--- */
.standoutHeader strong,
#right-nav-panel h2,
.drawer-content h3.margin0,
.drawer-content h4.margin0,
.popup h3:not(dialog *) {
  font-size: calc(var(--mainFontSize) * 1.15);
  font-weight: 600;
  letter-spacing: 0.03em;
  line-height: 2;
}

.standoutHeader strong::before,
#right-nav-panel h2::before,
.drawer-content h3.margin0::before,
.drawer-content h4.margin0::before,
.popup h3:not(dialog *)::before {
  content: none;
}

/* ============================================================
 * 输入框
 * ============================================================ */
input[type="text"],
input[type="number"],
input:not([type]),
textarea:not([type="search"]) {
  background-color: var(--SmartThemeShadowColor) !important;
  border: 1px solid var(--SmartThemeBorderColor) !important;
  border-radius: 4px;
}

input[type="text"]:focus,
input[type="number"]:focus,
input:not([type]):focus,
textarea:not([type="search"]):focus {
  border-color: var(--SmartThemeQuoteColor) !important;
}

textarea[type="search"] {
  background-color: transparent !important;
  border: none !important;
}

.text_pole {
  background-color: var(--SmartThemeShadowColor);
  border: 1px solid var(--SmartThemeBorderColor);
  border-radius: 4px;
}

/* ============================================================
 * 按钮
 * ============================================================ */
.menu_button {
  background-color: #1d2021;
  border: 1px solid var(--SmartThemeBorderColor);
  color: var(--SmartThemeBodyColor);
  border-radius: 4px;
}

.menu_button:hover {
  background-color: color-mix(in srgb, var(--SmartThemeQuoteColor) 25%, var(--SmartThemeShadowColor));
  border-color: var(--SmartThemeQuoteColor);
}

#delete_button,
#dialogue_del_mes_ok,
#dialogue_popup_ok,
.redWarningBG,
.red_button,
.mes_edit_cancel.menu_button {
  background-color: rgba(204, 36, 29, 1) !important;
  color: #fff !important;
}

.mes_button,
.mes_edit_buttons {
  filter: none !important;
}

.fa-solid:not(#load-spinner) {
  text-shadow: none !important;
}

/* ============================================================
 * 下拉框
 * ============================================================ */
select {
  background-color: var(--SmartThemeShadowColor) !important;
  color: var(--SmartThemeBodyColor);
  border: 1px solid var(--SmartThemeBorderColor) !important;
  border-radius: 4px;
  margin: 4px 0 !important;
}

select option:checked {
  color: var(--SmartThemeBlurTintColor);
  background-color: var(--SmartThemeBodyColor) !important;
}

select option {
  background-color: var(--SmartThemeBlurTintColor) !important;
}

/* ============================================================
 * 勾选框
 * ============================================================ */
input[type="checkbox"] {
  width: calc(var(--mainFontSize) * 0.9);
  height: calc(var(--mainFontSize) * 0.9);
  border: none;
  border-radius: 3px;
  background-color: var(--SmartThemeShadowColor);
  filter: none;
  box-shadow: 0 0 0 1px var(--SmartThemeEmColor);
}

input[type="checkbox"]::before {
  box-shadow: inset 1em 1em var(--SmartThemeQuoteColor);
}

/* ============================================================
 * 滑动条
 * ============================================================ */
input[type="range"] {
  background-color: var(--SmartThemeShadowColor) !important;
  border-radius: 4px;
  box-shadow: none;
}

input[type="range"]::-webkit-slider-thumb {
  background-color: var(--SmartThemeQuoteColor);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--SmartThemeQuoteColor) 40%, transparent);
  border-radius: 50%;
  width: 10px;
  height: 10px;
}

/* ============================================================
 * 盒子/面板
 * ============================================================ */
#left-nav-panel,
#right-nav-panel,
#character_popup,
#dialogue_popup,
#chat,
.draggable,
#select_chat_popup,
.popup:not(.transparent_dialogue_popup),
.drawer-content {
  padding: 10px;
  background-color: var(--SmartThemeBlurTintColor);
  border-radius: 6px;
  border: 1px solid var(--SmartThemeBorderColor);
}



#dialogue_popup_text {
  padding: 0 10px 0 0;
}

/* ---列表--- */
.list-group,
.options-content {
  border: 1px solid var(--SmartThemeBorderColor);
  border-radius: 5px;
  background-color: var(--SmartThemeShadowColor) !important;
}

#options {
  background-color: transparent !important;
  padding: 0;
}

/* ---头像--- */
.avatar img,
body.big-avatars .avatar img {
  box-shadow: none;
  border: none;
  border-radius: 6px;
}

#rm_button_characters,
#rm_button_panel_pin_div,
#lm_button_panel_pin_div,
#WI_button_panel_pin_div,
#char_connections_button {
  font-size: var(--mainFontSize);
}

/* ============================================================
 * 聊天区域
 * ============================================================ */
#sheld {
  top: calc(var(--topBarBlockSize));
  height: calc(100dvh - var(--topBarBlockSize) - 1px);
}

#chat {
  overflow-y: scroll;
  scrollbar-gutter: stable;
  align-items: stretch;
  max-height: calc(100dvh - var(--topBarBlockSize) - 20px) !important;
  padding: 8px 8px 8px 8px;
  background-color: var(--SmartThemeChatTintColor);
}

.mesAvatarWrapper .avatar {
  margin: calc(var(--mainFontSize) * 0.6) 0 calc(var(--mainFontSize) * 0.4) 0;
}

.mesIDDisplay,
.mes_timer,
.tokenCounterDisplay {
  display: block;
  color: var(--SmartThemeEmColor);
  font-size: calc(var(--mainFontSize) * 0.75);
  opacity: 0.7;
}

#chat .ch_name {
  position: relative;
  align-items: flex-end;
  padding: calc(var(--mainFontSize) * 0.8) 0;
  font-weight: 500;
}

#chat .ch_name::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 1px;
  background-color: var(--SmartThemeEmColor);
}

.mes {
  border: none !important;
  background-color: var(--SmartThemeChatTintColor) !important;
}

.mes_text {
  padding: calc(var(--mainFontSize) * 0.8) 0 0 0;
  line-height: 1.8;
}



.last_mes .mes_text {
  padding-right: 0;
}

.last_mes .mesAvatarWrapper {
  padding-bottom: 0;
}

div[is_user="false"].last_mes .mes_block {
  padding-bottom: 50px;
}

.last_mes .swipeRightBlock {
  margin: 0 10px 0 0;
}

div[is_user="true"] {
  background-color: var(--SmartThemeUserMesBlurTintColor) !important;
}

div[is_user="false"] {
  background-color: var(--SmartThemeBotMesBlurTintColor) !important;
}

div[is_user="true"] .avatar img {
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--SmartThemeUnderlineColor) 60%, transparent);
}

div[is_user="false"] .avatar img {
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--SmartThemeQuoteColor) 60%, transparent);
}

.swipe_left {
  left: 12px;
}

.swipeRightBlock {
  flex-direction: row-reverse;
  bottom: calc(var(--swipeCounterHeight) + var(--swipeCounterMargin));
}

#chat .mes.selected {
  background-color: rgba(204, 36, 29, 0.3) !important;
}

/* ---文档模式--- */
body.documentstyle #chat .ch_name::after { width: 0; }
body.documentstyle #chat .mes .mes_block { margin-right: 0; padding-bottom: 15px; }
body.documentstyle #chat .last_mes .mes_block { padding-bottom: 50px; }
body.documentstyle #chat .mes_text { margin-left: 0 !important; }

/* ---视觉小说模式--- */
body.waifuMode #chat {
  border: none;
  box-shadow: none;
}
body.waifuMode .zoomed_avatar { top: 70px; }

/* ============================================================
 * 推理块
 * ============================================================ */
.mes_reasoning_header {
  margin: 1em 0;
  padding: 7px 28px 7px 10px;
  background: color-mix(in srgb, var(--SmartThemeQuoteColor) 20%, transparent);
  border: 1px solid var(--SmartThemeQuoteColor);
  border-radius: 4px;
  color: var(--SmartThemeBodyColor);
}

.mes_reasoning_header span::before {
  content: none;
}

.mes_reasoning {
  border-left: 2px solid var(--SmartThemeQuoteColor);
}

/* ============================================================
 * 底栏
 * ============================================================ */
#form_sheld {
  margin: 0 auto;
}

#send_form {
  background-color: var(--SmartThemeBlurTintColor) !important;
  border: 1px solid var(--SmartThemeBorderColor) !important;
  border-radius: 6px;
  backdrop-filter: none;
  padding: 4px 8px;
  outline: none !important;
}

#send_form:focus,
#send_form:focus-within {
  outline: none !important;
  box-shadow: none !important;
}

#send_form textarea {
  background-color: transparent !important;
}

#send_form .fa-solid {
  font-size: calc(var(--mainFontSize) * 1.5);
}

/* ---QR--- */
#qr--bar > .qr--buttons .qr--button,
#qr--popout > .qr--body > .qr--buttons .qr--button {
  background-color: color-mix(in srgb, var(--SmartThemeQuoteColor) 25%, transparent);
  border-color: var(--SmartThemeQuoteColor) !important;
  border-radius: 4px !important;
}

#qr--bar > .qr--buttons .qr--button:hover,
#qr--popout > .qr--body > .qr--buttons .qr--button:hover {
  background-color: color-mix(in srgb, var(--SmartThemeQuoteColor) 45%, transparent) !important;
}

/* ============================================================
 * 提示词管理器
 * ============================================================ */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
  border-radius: 6px;
  background-color: var(--SmartThemeBlurTintColor);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:hover,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:focus {
  border-color: var(--SmartThemeQuoteColor);
  background-color: color-mix(in srgb, var(--SmartThemeQuoteColor) 15%, transparent);
}

/* ============================================================
 * 世界书
 * ============================================================ */
.world_entry {
  margin-top: 5px;
}

.wi-card-entry {
  border: none;
}

.select2-container .select2-selection--multiple {
  background-color: var(--SmartThemeBlurTintColor);
  border: none;
  border-radius: 4px;
}

.select2-container .select2-selection--multiple .select2-selection__choice,
.select2-container .select2-selection--single .select2-selection__choice {
  background-color: color-mix(in srgb, var(--SmartThemeUnderlineColor) 25%, transparent);
  border-radius: 3px;
}

/* ============================================================
 * 角色管理器
 * ============================================================ */
.character_select.is_fav .avatar {
  outline: 2px solid var(--SmartThemeQuoteColor);
}

.character_select.is_fav .ch_name {
  color: var(--SmartThemeQuoteColor);
}

#HotSwapWrapper > div::-webkit-scrollbar-thumb {
  background-color: var(--SmartThemeBorderColor);
}

/* ---背景图库--- */
.bg_example {
  box-shadow: none;
  border-color: var(--SmartThemeBorderColor);
  border-radius: 4px;
}

.bg_example.selected {
  border-color: var(--SmartThemeUnderlineColor);
}

/* ============================================================
 * 移动端适配
 * ============================================================ */
/* 移动端缩小头像，正文更宽 */
@media screen and (max-width: 1000px) {
  /* 手机端全部方角 */
  #sheld, #chat, #send_form, #top-settings-holder,
  #left-nav-panel, #right-nav-panel,
  .drawer-content, .mes, #form_sheld {
    border-radius: 0 !important;
  }
  #top-settings-holder,
  #top-settings-holder .drawer,
  #top-settings-holder .drawer-toggle,
  #top-settings-holder .drawer:first-child,
  #top-settings-holder .drawer:last-child,
  #top-settings-holder .drawer:first-child .drawer-toggle,
  #top-settings-holder .drawer:last-child .drawer-toggle {
    border-radius: 0 !important;
  }
  /* 头像保留圆角 */
  .avatar img, .mesAvatarWrapper .avatar {
    border-radius: 50% !important;
  }
  #left-nav-panel,
  #right-nav-panel {
    border-radius: 0 0 5px 5px;
  }
  .mes {
    position: relative !important;
    padding-top: 8px !important;
  }
  /* 头像：只钉在左上角，不拉满宽 */
  .mesAvatarWrapper {
    position: absolute !important;
    top: 8px !important;
    left: 4px !important;
    right: 4px !important;
    width: auto !important;
    min-width: 0 !important;
    height: auto !important;
    flex: none !important;
    display: flex !important;
    flex-direction: row !important;
    flex-wrap: wrap !important;
    align-items: flex-start !important;
    align-content: flex-start !important;
    gap: 4px 6px !important;
    z-index: 2 !important;
    pointer-events: none !important;
  }
  .mesAvatarWrapper .avatar {
    width: 36px !important;
    height: 36px !important;
    min-width: 36px !important;
    min-height: 36px !important;
    margin: 0 !important;
    flex: 0 0 36px !important;
    pointer-events: auto !important;
  }
  .mesAvatarWrapper .avatar img {
    width: 36px !important;
    height: 36px !important;
  }
  /* 计数器换到头像下一行 */
  .mesAvatarWrapper::after {
    content: "" !important;
    flex: 0 0 100% !important;
    width: 0 !important;
    height: 0 !important;
    order: 1 !important;
  }
  #chat .mes .mes_block {
    width: 100% !important;
    padding: 0 !important;
  }
  /* 名字区：与头像顶对齐；名字+时间+图标尽量同一行 */
  #chat .mes .ch_name {
    padding: 0 4px 2px 46px !important;
    min-height: 36px !important;
    margin: 0 0 22px 0 !important; /* 给下方计数器行留空 */
    display: flex !important;
    align-items: center !important; /* 单行时与头像垂直居中 */
  }
  #chat .mes .ch_name .alignItemsBaseline {
    display: flex !important;
    flex-wrap: wrap !important;
    align-items: center !important;
    column-gap: 6px !important;
    row-gap: 2px !important;
    width: 100% !important;
  }
  /* 关键：不要 100% 宽，否则时间必掉第二行 */
  #chat .mes .ch_name .name_text {
    flex: 0 1 auto !important;
    min-width: 0 !important;
    max-width: 100% !important;
    display: inline !important;
    line-height: 1.3 !important;
  }
  #chat .mes .ch_name .mes_ghost {
    flex: 0 0 auto !important;
  }
  #chat .mes .timestamp {
    display: inline-flex !important;
    align-items: center !important;
    white-space: nowrap !important;
    flex: 0 0 auto !important;
    line-height: 1.2 !important;
    margin: 0 !important;
    opacity: 0.8 !important;
    font-size: calc(var(--mainFontSize) * 0.78) !important;
  }
  #chat .mes .timestamp-icon {
    display: inline-block !important;
    width: 1em !important;
    height: 1em !important;
    flex: 0 0 1em !important;
    margin: 0 0 0 4px !important;
    vertical-align: middle !important;
    line-height: 1 !important;
  }
  #chat .mes .timestamp-icon,
  #chat .mes .timestamp-icon svg {
    width: 1em !important;
    height: 1em !important;
    max-width: 1em !important;
    max-height: 1em !important;
    display: inline-block !important;
    vertical-align: middle !important;
  }
  #chat .mes .ch_name::after {
    display: none !important;
  }
  /* 计数器：横排芯片，缩进到名字左对齐 */
  #chat .mes .mesIDDisplay,
  #chat .mes .mes_timer,
  #chat .mes .tokenCounterDisplay {
    order: 2 !important;
    position: static !important;
    display: inline-block !important;
    top: auto !important;
    left: auto !important;
    margin: 0 !important;
    padding: 1px 6px !important;
    font-size: calc(var(--mainFontSize) * 0.62) !important;
    opacity: 0.7 !important;
    line-height: 1.3 !important;
    white-space: nowrap !important;
    background: color-mix(in srgb, var(--SmartThemeBorderColor) 55%, transparent) !important;
    border-radius: 4px !important;
    pointer-events: auto !important;
  }
  #chat .mes .mesIDDisplay {
    /* 抵消 padding-left:6px，让芯片框左边缘与名字对齐，而不是文字对齐 */
    margin-left: calc(46px - 6px) !important;
  }
  /* 空 timer 不占位（用户消息） */
  #chat .mes .mes_timer:empty {
    display: none !important;
  }
  #chat .mes .tokenCounterDisplay:empty {
    display: none !important;
  }
  /* 正文 */
  #chat .mes .mes_text {
    padding-left: 6px !important;
    padding-right: 2px !important;
    padding-top: 8px !important;
    padding-bottom: 40px !important;
    margin-top: 0 !important;
    border-top: 1px solid color-mix(in srgb, var(--SmartThemeEmColor) 28%, transparent) !important;
  }
}

@supports (-webkit-touch-callout: none) {
  .drawer-content:not(#left-nav-panel):not(#right-nav-panel) {
    max-width: 100dvw;
    top: var(--topBarBlockSize);
  }
}

/* ============================================================
 * 标题下横线
 * ============================================================ */
.standoutHeader:not(h4),
#rm_PinAndTabs,
#top-settings-holder .drawer:not(:first-child):not(:last-child) .drawer-content .alignItemsBaseline.wide100p,
#rm_api_block .flex-container.alignItemsBaseline,
#title_api,
#AdvancedFormatting .flex-container.alignItemsBaseline:not(h3),
#WorldInfo .alignitemscenter:not(#world_popup *),
#Backgrounds .bg-header-row-1,
#user-settings-block div[name="userSettingsRowOne"],
#rm_extensions_block .alignitemscenter.flex-container.wide100p:not(.justifyCenter) {
  background-image: none;
  border: none;
  border-bottom: 1px solid var(--SmartThemeBorderColor);
  margin-bottom: calc(var(--mainFontSize) * 0.4);
  padding-bottom: calc(var(--mainFontSize) * 0.2);
}

.drawer-content .alignItemsBaseline {
  align-items: center !important;
}

#title_api {
  padding-bottom: 0;
}

#title_api::before,
#Backgrounds h3.margin0.flex2::before,
#rm_extensions_block .margin0.flex1::before,
#rm_button_selected_ch h2::before {
  margin-right: 5px;
}

.custom-mermaid {
  background-color: var(--SmartThemeShadowColor);
}

.standoutHeader.inline-drawer-header {
  padding: 5px 8px 5px 12px !important;
}


/* ============================================================
 * 补回丢失的UI元素
 * ============================================================ */

/* ---世界书条目分割线--- */
.world_entry {
  border-bottom: 1px solid var(--SmartThemeBorderColor) !important;
  padding-bottom: 8px !important;
  margin-bottom: 8px !important;
}

.world_entry:last-child {
  border-bottom: none !important;
}

/* ---输入框边框--- */
#send_form {
  border: 1px solid var(--SmartThemeBorderColor) !important;
}

#send_textarea {
  border: none !important;
  border-bottom: 3px solid var(--SmartThemeQuoteColor) !important;
  border-radius: 0 !important;
  padding: 6px 10px !important;
  min-height: 40px !important;
  font-size: calc(var(--mainFontSize) * 1.05) !important;
  outline: none !important;
}

#send_textarea:focus {
  outline: none !important;
  box-shadow: none !important;
}


/* ---抽屉内部分割线--- */
.drawer-content .inline-drawer {
  border-bottom: none;
}

/* ---提示词管理器条目边框--- */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
  border: 1px solid var(--SmartThemeBorderColor) !important;
}

/* ---角色列表条目分割线--- */
.character_select {
  border-bottom: 1px solid var(--SmartThemeBorderColor);
}

/* ---面板内分割线--- */
#right-nav-panel hr,
#left-nav-panel hr {
  border: none;
  border-top: 1px solid var(--SmartThemeBorderColor);
  margin: 8px 0;
}

/* ---设置区块分割--- */
#user-settings-block .setting_section {
  border-bottom: 1px solid var(--SmartThemeBorderColor);
  padding-bottom: 8px;
  margin-bottom: 8px;
}

/* ============================================================
 * 背景层 - v3.1 新增
 * body 底色 + #chat 透明 + 暗纹叠加
 * ============================================================ */

body {
  background-color: #1d2021 !important;
}

/* 全屏暗色遮罩（聊天区域外） */
body::before {
  content: "";
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background-color: rgba(29, 32, 33, 0.92);
  pointer-events: none;
  z-index: 0;
}

/* 暗纹叠加层（在遮罩之上，聊天区之下） */
body::after {
  content: "" !important;
  position: fixed !important;
  top: 0 !important; left: 0 !important; right: 0 !important; bottom: 0 !important;
  background-image:
    repeating-linear-gradient(45deg, transparent, transparent 35px, rgba(131, 165, 152, 0.008) 35px, rgba(131, 165, 152, 0.008) 70px),
    repeating-linear-gradient(-45deg, transparent, transparent 35px, rgba(131, 165, 152, 0.008) 35px, rgba(131, 165, 152, 0.008) 70px) !important;
  pointer-events: none !important;
  z-index: 0 !important;
}

/* #chat 用 JSON 字段的 chat_tint_color（已改为 0.75 透明） */
/* 消息背景透明，让 chat_tint 透过来 */
.mes {
  background-color: transparent !important;
}

div[is_user="true"],
div[is_user="false"] {
  background-color: transparent !important;
}

/* ============================================================
 * 图标悬停发光动效 - v3.2
 * ============================================================ */

/* 所有交互图标统一 transition */
.interactable,
.fa-solid:not(#load-spinner),
.drawer-icon,
.menu_button .fa-solid,
#send_form .fa-solid,
#send_form a,
#top-settings-holder .fa-solid,
#top-bar .fa-solid {
  transition: filter 0.35s ease-out, transform 0.35s ease-out;
}

/* 通用 hover 发光 + 放大 */
.interactable:hover,
.fa-solid:not(#load-spinner):hover,
.drawer-icon:hover,
#top-bar .fa-solid:hover {
  filter: drop-shadow(0 0 4px rgba(131, 165, 152, 0.4));
}

/* 底部三按钮更强发光 + 放大 */
#send_form .fa-solid:hover,
#send_form a:hover {
  filter: drop-shadow(0 0 6px rgba(131, 165, 152, 0.6));
}

/* 按钮内图标放大 */


/* 角色头像悬停微光 */
.avatar img,
.character_select .avatar img {
  transition: filter 0.35s ease-out;
}

.avatar img:hover,
.character_select:hover .avatar img {
  filter: drop-shadow(0 0 6px rgba(131, 165, 152, 0.3));
}

/* ============================================================
 * 底部三按钮各自动效 - v3.3 新增
 * 汉堡菜单→抖动 / 魔杖→旋转 / 发送→书写摆动
 * ============================================================ */

/* --- 汉堡菜单：hover 抖动 --- */
#options_button .fa-solid,
#options_button {
  transition: filter 0.35s ease-out;
}

#options_button:hover .fa-solid,
#options_button:hover {
  animation: icon-shake 0.4s ease-in-out;
  filter: drop-shadow(0 0 4px rgba(131, 165, 152, 0.4));
}

@keyframes icon-shake {
  0%, 100% { transform: translateX(0) rotate(0); }
  20% { transform: translateX(-2px) rotate(-3deg); }
  40% { transform: translateX(2px) rotate(3deg); }
  60% { transform: translateX(-2px) rotate(-3deg); }
  80% { transform: translateX(2px) rotate(3deg); }
}

/* --- 魔杖：hover 旋转 --- */
#extensionsMenuButton {
  transition: filter 0.35s ease-out;
}

#extensionsMenuButton:hover {
  filter: drop-shadow(0 0 4px rgba(131, 165, 152, 0.4));
}

@keyframes icon-spin {
  0% { transform: rotate(0); }
  100% { transform: rotate(360deg); }
}

/* --- 发送按钮：hover 发光 + active 变暗（不用transform防撑边框） --- */
#send_but {
  transition: filter 0.35s ease-out, opacity 0.2s ease-out;
  filter: drop-shadow(0 0 2px rgba(131, 165, 152, 0.2));
}

#send_but:hover {
  filter: drop-shadow(0 0 8px rgba(131, 165, 152, 0.6));
}

#send_but:active {
  filter: drop-shadow(0 0 4px rgba(131, 165, 152, 0.3));
  opacity: 0.7;
}



/* ============================================================
 * 发送按钮 - mdi:feather 羽毛笔 + 书写轨迹动效 - v3.6
 * ============================================================ */
#send_but::before {
  content: "" !important;
  display: inline-block !important;
  width: 1.2em !important;
  height: 1.2em !important;
  background-image: url("https://api.iconify.design/mdi/feather.svg?color=%23fe8019"), url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20100%204%22%20preserveAspectRatio%3D%22none%22%3E%3Cpath%20d%3D%22M0%202%20Q25%200%2050%202%20T100%202%22%20fill%3D%22none%22%20stroke%3D%22%23fe8019%22%20stroke-width%3D%222%22%20stroke-linecap%3D%22round%22%2F%3E%3C%2Fsvg%3E") !important;
  background-repeat: no-repeat, no-repeat !important;
  background-position: center, left 100% !important;
  background-size: contain, 0% 2px !important;
  transition: background-size 0.8s ease-out, transform 0.3s ease-out !important;
  transform-origin: 50% 80% !important;
}

#send_but:hover::before {
  background-size: contain, 100% 2px !important;
  animation: quill-swing 1.5s ease-in-out infinite !important;
}

@keyframes quill-swing {
  0%, 100% { transform: rotate(-5deg); }
  50% { transform: rotate(5deg); }
}

/* 书写轨迹 */
#send_but {
  position: relative !important;
}

#send_but::after {
  content: "" !important;
  position: absolute !important;
  bottom: 0 !important;
  left: 50% !important;
  width: 0 !important;
  height: 1px !important;
  background: linear-gradient(90deg, transparent, #fe8019, transparent) !important;
  pointer-events: none !important;
}

#send_but:hover::after {
  animation: quill-trail 1.5s ease-in-out infinite !important;
}

@keyframes quill-trail {
  0% { width: 0; left: 50%; opacity: 0; }
  30% { opacity: 1; }
  50% { width: 120%; left: -10%; opacity: 1; }
  70% { opacity: 1; }
  100% { width: 0; left: 50%; opacity: 0; }
}

